import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:8000';

const api = axios.create({
  baseURL: API_BASE,
  withCredentials: true,
  headers: {
    'Content-Type': 'application/json',
  },
});

export const authAPI = {
  register: (data) => api.post('/api/auth/register.php', data),
  login: (data) => api.post('/api/auth/login.php', data),
  logout: () => api.post('/api/auth/logout.php'),
  checkSession: () => api.get('/api/auth/check_session.php'),
};

export const hotelsAPI = {
  list: (search) => api.get('/api/hotels/list.php', { params: { search } }),
  get: (id) => api.get('/api/hotels/get.php', { params: { id } }),
  create: (data) => api.post('/api/hotels/create.php', data),
  update: (data) => api.put('/api/hotels/update.php', data),
  delete: (id) => api.delete('/api/hotels/delete.php', { params: { id } }),
  search: (params) => api.get('/api/hotels/search.php', { params }),
};

export const roomsAPI = {
  list: (hotelId) => api.get('/api/rooms/list.php', { params: { hotel_id: hotelId } }),
  create: (data) => api.post('/api/rooms/create.php', data),
  update: (data) => api.put('/api/rooms/update.php', data),
  delete: (id) => api.delete('/api/rooms/delete.php', { params: { id } }),
};

export const bookingsAPI = {
  create: (data) => api.post('/api/bookings/create.php', data),
  listUser: () => api.get('/api/bookings/list_user.php'),
  listOwner: () => api.get('/api/bookings/list_owner.php'),
  confirm: (id) => api.put('/api/bookings/confirm.php', { id }),
  cancel: (id) => api.put('/api/bookings/cancel.php', { id }),
};

export const eventsAPI = {
  list: (hotelId) => api.get('/api/events/list.php', { params: { hotel_id: hotelId } }),
  create: (data) => api.post('/api/events/create.php', data),
  update: (data) => api.put('/api/events/update.php', data),
  delete: (id) => api.delete('/api/events/delete.php', { params: { id } }),
};

export const offersAPI = {
  list: (hotelId) => api.get('/api/offers/list.php', { params: { hotel_id: hotelId } }),
  create: (data) => api.post('/api/offers/create.php', data),
  update: (data) => api.put('/api/offers/update.php', data),
  delete: (id) => api.delete('/api/offers/delete.php', { params: { id } }),
};

export const placesAPI = {
  list: (hotelId) => api.get('/api/places/list.php', { params: { hotel_id: hotelId } }),
  create: (data) => api.post('/api/places/create.php', data),
  update: (data) => api.put('/api/places/update.php', data),
  delete: (id) => api.delete('/api/places/delete.php', { params: { id } }),
};

export const adminAPI = {
  hotels: () => api.get('/api/admin/hotels.php'),
  deleteHotel: (id) => api.delete('/api/admin/delete_hotel.php', { params: { id } }),
};

export default api;
